import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** 核對完整封裝、既有方法與新增轉移邊界，數值／送包核心不另行實作。 */
public final class CompanionManaTransferDelta {
 static final String P="local/lito381/server/",COM=P+"NativePlayerCommit",E=P+"NativeEquipmentDefense",H=P+"NativeCompanionManaTransfer";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] method(ClassNode c,MethodNode m){var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;var copy=new MethodNode(m.access,m.name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);q.methods.add(copy);var w=new ClassWriter(0);q.accept(w);return w.toByteArray();}
 public static void main(String[]args)throws Exception{try(var before=new JarFile(args[0]);var after=new JarFile(args[1])){
  var names=new HashSet<String>();var changed=new TreeSet<String>();for(var e:Collections.list(before.entries())){names.add(e.getName());var n=after.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed "+e.getName());if(!Arrays.equals(before.getInputStream(e).readAllBytes(),after.getInputStream(n).readAllBytes()))changed.add(e.getName());}var fresh=new TreeSet<String>();for(var e:Collections.list(after.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(COM+".class",E+".class"))||!fresh.equals(Set.of(H+".class")))throw new AssertionError("archive "+changed+" "+fresh);
  for(var name:List.of(COM,E)){var b=read(before,name);var a=read(after,name);if(b.fields.size()!=a.fields.size())throw new AssertionError("new fields");for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=a.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||x.access!=y.access||!Objects.equals(x.value,y.value))throw new AssertionError("field schema");}for(var m:b.methods){var q=a.methods.stream().filter(v->v.name.equals(m.name)&&v.desc.equals(m.desc)).findFirst().orElseThrow();if(name.equals(E)&&m.name.equals("apply")){int n=0;for(var node:q.instructions)if(node instanceof MethodInsnNode v&&v.owner.equals(H)&&v.name.equals("drain")){v.owner=P+"NativeCombatAttacker";v.name="debit";n++;}if(n!=1)throw new AssertionError("one consumer");}if(!Arrays.equals(method(b,m),method(a,q)))throw new AssertionError("original method "+name+"."+m.name);}if(a.methods.size()!=b.methods.size()+(name.equals(COM)?1:0))throw new AssertionError("method schema");}
  var h=read(after,H);if(!h.fields.isEmpty())throw new AssertionError("stateless helper");for(var m:h.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW&&!t.desc.equals("java/lang/IllegalStateException"))throw new AssertionError("new owner "+t.desc);if(n instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("AccountRepository")||v.owner.endsWith("GameStateStore")||v.name.equals("nativeDeInventory")))throw new AssertionError("SQL/file/inventory dependency");}
 }System.out.println("PASS archive isolation, every original method and field retained, one exact equipment consumer replacement, stateless transfer helper, no new workers/timers/TLS/registry/SQL/file/inventory dependency");}
}
